// 05 - Scheduler: preemption, equal-priority yielding, per-core sleep, load spread.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  volatile unsigned g_preempted = 0;
  volatile unsigned g_low_saw = 0;
  volatile unsigned g_high_core = 0xff;

  void*
  low_spinner (void*)
  {
    // Busy on core 1: only a preemption lets the high thread set the flag.
    store (g_low_saw, spin_until (g_preempted, ms (500)) ? 1u : 0u);
    return nullptr;
  }

  void*
  high_sleeper (void*)
  {
    sysclock.sleep_for (ms (10));
    store (g_high_core, mtp_board::cpu_id ());
    store (g_preempted, 1u);
    return nullptr;
  }

  constexpr unsigned yields = 100;
  volatile unsigned g_yield_go = 0;
  unsigned char g_order[2 * yields];
  volatile unsigned g_order_at = 0;

  void*
  yielder (void* arg)
  {
    const auto id = static_cast<unsigned char> (from_arg (arg));
    while (load (g_yield_go) == 0)
      {
        this_thread::yield ();
      }
    for (unsigned i = 0; i < yields; ++i)
      {
        {
          interrupts::critical_section ics;
          g_order[g_order_at] = id;
          g_order_at = g_order_at + 1;
        }
        this_thread::yield ();
      }
    return nullptr;
  }

  volatile unsigned g_slept_ticks[ncpu];

  void*
  timed_sleep (void* arg)
  {
    const unsigned core = from_arg (arg);
    const auto begin = sysclock.now ();
    sysclock.sleep_for (ms (50));
    store (g_slept_ticks[core], static_cast<unsigned> (sysclock.now () - begin));
    return nullptr;
  }

  constexpr unsigned workers = 2 * ncpu;
  volatile unsigned g_worker_cores[workers];

  void*
  busy_worker (void* arg)
  {
    const unsigned slot = from_arg (arg);
    unsigned mask = 0;
    const auto begin = sysclock.now ();
    while (sysclock.now () - begin < ms (60))
      {
        busy_loop (2000);
        mask |= 1u << mtp_board::cpu_id ();
      }
    store (g_worker_cores[slot], mask);
    return nullptr;
  }
} // namespace

mt::static_suite suite_scheduler{
  "05 - Scheduler", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("a higher priority preempts a busy thread on core 1",
             [] (auto& t) {
               store (g_preempted, 0u);
               store (g_low_saw, 0u);
               store (g_high_core, 0xffu);
               thread* low = spawn ("mtp-busy-low", low_spinner, nullptr, 1);
               thread* high = spawn ("mtp-preempt", high_sleeper, nullptr, 1,
                                     thread::priority::above_normal);
               finish (high);
               finish (low);
               t.expect (mt::eq (load (g_high_core), 1u))
                   << "the high thread ran on core 1";
               t.expect (mt::eq (load (g_low_saw), 1u))
                   << "while the low thread was still busy there";
             });

    ts.test ("yield alternates two equal-priority threads", [] (auto& t) {
      store (g_yield_go, 0u);
      g_order_at = 0;
      thread* a = spawn ("mtp-yield-a", yielder, as_arg (1), 1);
      thread* b = spawn ("mtp-yield-b", yielder, as_arg (2), 1);
      sysclock.sleep_for (ms (5));
      store (g_yield_go, 1u);
      finish (a);
      finish (b);
      unsigned switches = 0;
      for (unsigned i = 1; i < load (g_order_at); ++i)
        {
          switches += g_order[i] != g_order[i - 1] ? 1u : 0u;
        }
      t.expect (mt::eq (load (g_order_at), 2 * yields)) << "both ran to the end";
      t.expect (mt::ge (switches, yields)) << fmt ("%u switches of 199", switches);
    });

    ts.test ("sleep_for () lasts as asked on every core", [] (auto& t) {
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          store (g_slept_ticks[core], 0u);
          threads[core] = spawn ("mtp-sleep", timed_sleep, as_arg (core),
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      for (unsigned core = 0; core < ncpu; ++core)
        {
          const unsigned slept = load (g_slept_ticks[core]);
          t.expect (mt::all_of (mt::ge (slept, static_cast<unsigned> (ms (50))),
                                mt::le (slept, static_cast<unsigned> (ms (60)))))
              << fmt ("core %u: 50 ms, within 10 ms", core);
        }
    });

    ts.test ("unpinned busy threads spread over the cores", [] (auto& t) {
      thread* threads[workers] = {};
      for (unsigned i = 0; i < workers; ++i)
        {
          store (g_worker_cores[i], 0u);
          threads[i] = spawn ("mtp-spread", busy_worker, as_arg (i), -1);
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      unsigned used = 0;
      for (const auto& mask : g_worker_cores)
        {
          used |= load (mask);
        }
      unsigned cores = 0;
      for (unsigned c = 0; c < ncpu; ++c)
        {
          cores += (used >> c) & 1u;
        }
      t.expect (mt::eq (cores, ncpu)) << fmt ("cores used: mask 0x%x", used);
    });
  }
};
